    static _authenticationEventHandler(self, evt, data) {
        if (TouchControls.isEnabled() && [q.EVENTS.PLAYER_AUTHENTICATED, q.EVENTS.GUEST_ADDED, q.EVENTS.GUESTS_ADDED].includes(evt)) {
            for (const id of (Array.isArray(data) ? data : [data])) ks.addInputManager(id, "touch");
            return;
        }
        switch (evt) {
            case q.EVENTS.PLAYER_AUTHENTICATED:
            case q.EVENTS.GUEST_ADDED:
            {
                // Assign controls to player.
                le.enqueueOverlay(
                    M.ControlsOverlay,
                    { playerId: data }
                );

                break;
            }
            case q.EVENTS.GUESTS_ADDED:
            {
                // Assign controls to players.
                for (let i = 0; i < data.length; ++i) {
                    le.enqueueOverlay(
                        M.ControlsOverlay,
                        { playerId: data[i], count: data.length > 1 ? i + 1 : undefined }
                    );
                }

                break;
            }
            case q.EVENTS.PLAYER_DEAUTHENTICATED:
            case q.EVENTS.GUEST_REMOVED:
            {
                ks.removeInputManager(data);
                break;
            }
        }
    }
